exercises.solution:
ALL_FEATURES = frozenset(
    {"deletion_vectors", "column_mapping_name", "column_mapping_id", "timestamp_ntz", "liquid_clustering"}
)
SUPPORTED: dict[str, frozenset[str]] = {
    "spark_2_0": ALL_FEATURES,
    "sql_endpoint": ALL_FEATURES - {"column_mapping_id", "timestamp_ntz"},
    "direct_lake": ALL_FEATURES - {"timestamp_ntz"},
    "python_notebook": frozenset({"timestamp_ntz"}),
}


def unsupported(reader: str, features: set[str]) -> list[str]:
    """Table features a Fabric reader does not support.

    Raises:
        KeyError: For an unknown reader.
    """
    return sorted(features - SUPPORTED[reader])
